public class Problem2_WarehouseBinGridScan { static int[] warehouseSummary(int[][]g){if(g.length==0||g[0].length==0)return new int[]{0,-1,-1};int sum=0,max=-1,mr=0,mc=0;for(int r=0;r<g.length;r++)for(int c=0;c<g[r].length;c++){sum+=g[r][c];if(g[r][c]>max){max=g[r][c];mr=r;mc=c;}}return new int[]{sum,mr,mc};} public static void main(String[]x){int[]s=warehouseSummary(new int[][]{{4,9,2},{7,1,6},{3,12,5}});System.out.println("total="+s[0]+", maxCoordinate=("+s[1]+", "+s[2]+")");}}